140		@VisibleForTesting
141		protected void changeDcMeta(DcMeta current, DcMeta future, final long metaLoadTime) {
142	
143			if (metaLoadTime <= metaModifyTime.get()) {
144				logger.info("[run][skip change dc meta]" + META_MODIFY_JUST_NOW_TEMPLATE, metaModifyTime.get(), metaLoadTime);
145				return;
146			}
147	
148			DcMetaComparator dcMetaComparator = new DcMetaComparator(current, future);
149			dcMetaComparator.compare();
150	
151			if (dcMetaComparator.totalChangedCount() - drClusterNums(dcMetaComparator) > META_MODIFY_PROTECT_COUNT) {
152				logger.error("[run][modify count size too big]{}, {}, {}", META_MODIFY_PROTECT_COUNT,
153						dcMetaComparator.totalChangedCount(), dcMetaComparator);
154				EventMonitor.DEFAULT.logAlertEvent("remove too many:" + dcMetaComparator.totalChangedCount());
155				return;
156			}
157	
158			DcMetaManager newDcMetaManager = DefaultDcMetaManager.buildFromDcMeta(future);
159			boolean dcMetaUpdated = false;
160			synchronized (this) {
161				if (metaLoadTime > metaModifyTime.get()) {
162					dcMetaManager.set(newDcMetaManager);
163					dcMetaUpdated = true;
164				}
165			}
166	
167			if (!dcMetaUpdated) {
168				logger.info("[run][skip change dc meta]" + META_MODIFY_JUST_NOW_TEMPLATE, metaModifyTime, metaLoadTime);
169				return;
170			}
171	
172			logger.info("[run][change dc meta]");
173			if (dcMetaComparator.totalChangedCount() > 0) {
174				logger.info("[run][change]{}", dcMetaComparator);
175				EventMonitor.DEFAULT.logEvent(META_CHANGE_TYPE, String.format("[add:%s, del:%s, mod:%s]",
176						StringUtil.join(",", (clusterMeta) -> clusterMeta.getId(), dcMetaComparator.getAdded()),
177						StringUtil.join(",", (clusterMeta) -> clusterMeta.getId(), dcMetaComparator.getRemoved()),
178						StringUtil.join(",", (comparator) -> comparator.idDesc(), dcMetaComparator.getMofified()))
179				);
180				notifyObservers(dcMetaComparator);
181			}
182		}
