31	public class KeeperStateChangeJob extends AbstractCommand<Void>{
32		
33		private List<KeeperMeta> keepers;
34		private Pair<String, Integer> activeKeeperMaster;
35		private RouteMeta routeForActiveKeeper;
36		private SimpleKeyedObjectPool<Endpoint, NettyClient> clientPool;
37		private int delayBaseMilli = 1000;
38		private int retryTimes = 5;
39		private ScheduledExecutorService scheduled;
40		private Executor executors;
41		private Command<?> activeSuccessCommand;
42	
43		public KeeperStateChangeJob(List<KeeperMeta> keepers,
44									Pair<String, Integer> activeKeeperMaster,
45									RouteMeta routeForActiveKeeper,
46									SimpleKeyedObjectPool<Endpoint, NettyClient> clientPool
47				, ScheduledExecutorService scheduled, Executor executors){
48			this(keepers, activeKeeperMaster, routeForActiveKeeper, clientPool, 1000, 5, scheduled, executors);
49		}
50		
51		public KeeperStateChangeJob(List<KeeperMeta> keepers,
52									Pair<String, Integer> activeKeeperMaster,
53									RouteMeta routeForActiveKeeper,
54									SimpleKeyedObjectPool<Endpoint, NettyClient> clientPool
55				, int delayBaseMilli, int retryTimes, ScheduledExecutorService scheduled, Executor executors){
56			this.keepers = new LinkedList<>(keepers);
57			this.activeKeeperMaster = activeKeeperMaster;
58			this.routeForActiveKeeper = routeForActiveKeeper;
59			this.clientPool = clientPool;
60			this.delayBaseMilli = delayBaseMilli;
61			this.retryTimes = retryTimes;
62			this.scheduled = scheduled;
63			this.executors = executors;
64		}
65	
66		@Override
67		public String getName() {
68			return "keeper change job";
69		}
70	
71		@Override
72		protected void doExecute() throws CommandExecutionException {
73	
74			KeeperMeta activeKeeper = null;
75			for(KeeperMeta keeperMeta : keepers){
76				if(keeperMeta.isActive()){
77					activeKeeper = keeperMeta;
78					break;
79				}
80			}
81	
82			if(activeKeeper == null){
83				future().setFailure(new Exception("can not find active keeper:" + keepers));
84				return;
85			}
86			SequenceCommandChain chain = new SequenceCommandChain(false);
87	
88			if(activeKeeperMaster != null){
89				Command<?> setActiveCommand = createKeeperSetStateCommand(activeKeeper, activeKeeperMaster);
90				addActiveCommandHook(setActiveCommand);
91				chain.add(setActiveCommand);
92			}
93	
94			ParallelCommandChain backupChain = new ParallelCommandChain(executors);
95			
96			for(KeeperMeta keeperMeta : keepers){
97				if(!keeperMeta.isActive()){
98					Command<?> backupCommand = createKeeperSetStateCommand(keeperMeta, new Pair<String, Integer>(activeKeeper.getIp(), activeKeeper.getPort()));
99					backupChain.add(backupCommand);
100				}
101			}
102	
103			chain.add(backupChain);
104			
105			chain.execute().addListener(new CommandFutureListener<Object>() {
106				
107				@Override
108				public void operationComplete(CommandFuture<Object> commandFuture) throws Exception {
109					
110					if(commandFuture.isSuccess()){
111						future().setSuccess(null);
112					}else{
113						future().setFailure(commandFuture.cause());
114					}
115				}
116			});
117		}
118	
119		private Command<?> createKeeperSetStateCommand(KeeperMeta keeper, Pair<String, Integer> masterAddress) {
120			
121			SimpleObjectPool<NettyClient> pool = new XpipeObjectPoolFromKeyed<Endpoint, NettyClient>(clientPool, new DefaultEndPoint(keeper.getIp(), keeper.getPort()));
122	
123			KeeperSetStateCommand command =  new KeeperSetStateCommand(pool,
124					keeper.isActive() ? KeeperState.ACTIVE : KeeperState.BACKUP,
125					masterAddress,
126					keeper.isActive() ? routeForActiveKeeper : null,
127					scheduled);
128			return CommandRetryWrapper.buildCountRetry(retryTimes, new RetryDelay(delayBaseMilli), command, scheduled);
129		}
130	
131		@Override
132		protected void doReset(){
133			throw new UnsupportedOperationException();
134		}
135		
136		public void setActiveSuccessCommand(Command<?> activeSuccessCommand) {
137			this.activeSuccessCommand = activeSuccessCommand;
138		}
139	
140		@SuppressWarnings({ "unchecked", "rawtypes" })
141		private void addActiveCommandHook(final Command<?> setActiveCommand) {
142			
143			setActiveCommand.future().addListener(new CommandFutureListener() {
144	
145				@Override
146				public void operationComplete( CommandFuture commandFuture) throws Exception {
147					
148					if(commandFuture.isSuccess() && activeSuccessCommand != null){
149						logger.info("[addActiveCommandHook][set active success, execute hook]{}, {}", setActiveCommand, activeSuccessCommand);
150						activeSuccessCommand.execute();
151					}
152				}
153			});
154		}
155	
156		@Override
157		public String toString() {
158			return String.format("[%s] master: %s",
159					StringUtil.join(",", (keeper) -> String.format("%s.%s", keeper.desc(), keeper.isActive()), keepers),
160					activeKeeperMaster);
161		}
162	}
